#include <bits/stdc++.h>
using namespace std;
int main(){long long n,q; cin>>n>>q;
 deque<pair<string,long long>> dq;
 for(long long i=0;i<n;i++){string p; long long d; cin>>p>>d; dq.push_back({p,d});}
 long long time=0; vector<pair<string,long long>> out;
 while(!dq.empty()){ auto[p,r]=dq.front(); dq.pop_front();
  long long run=min(r,q); time+=run; r-=run;
  if(r==0) out.push_back({p,time}); else dq.push_back({p,r}); }
 for(auto&[p,t]:out) cout<<p<<" "<<t<<"\n"; return 0;}
